#!/usr/bin/env bash
# experiments_md 20261003_05 §5 item 43b (design fixed 2026-11-09 01:18 JST; user 「蓄積による蜜->疎の学習時の摂動実験は実施」):
# one seed of L'_K, the S2 accumulation teacher 27468's recipe (Boston 15 / Singapore 10 sweeps, per-object compensation,
# MeanVFE, 20 epochs, 2 GPUs x 3) with each platform block thinned at random per 1.5-m range bin to that platform's
# single-sweep in-grid point count, then the label recount (cfgs/da-ieee-access-analysis/item43/centerpoint-i43b-lprime-k.yaml,
# generated by analysis/make_item43_configs.py; gate and checks in experiments_md 20261109_01). The in-run evaluation on
# single-sweep nuScenes val (epochs 19 / 20) is the reading, so no successor. ANALYSIS: nuScenes TRAIN labels train it.
# Seed 666 passes neither --seed nor --ddp_sampler_seed (as 27468); seed 667 passes both (user policy 2026-11-09).
#   bash scripts/_item43b_launch_20261109.sh <seed>      # 666 or 667, one call per free slot of the 12-job cap
set -euo pipefail
cd /home/koyama/code/ST3D/tools
SEED=${1:?seed}
case "$SEED" in
  666) FLAGS=() ;;
  667) FLAGS=(--seed 667 --ddp_sampler_seed) ;;
  *) echo "seed $SEED: item 43b runs 666 and 667 only" >&2; exit 2 ;;
esac
CFG=cfgs/da-ieee-access-analysis/item43/centerpoint-i43b-lprime-k.yaml
jid() { sed -n 's/^submitted job \([0-9]*\):.*/\1/p'; }
H="Item 43b (T05 §5, design fixed 2026-11-09 01:18 JST), labelled ANALYSIS (nuScenes TRAIN labels)"
T=$(EST_H=26 WANDB_NOTES="$H: L'_K seed $SEED, the S2 accumulation teacher 27468's recipe (n008 15 / n015 10 sweeps, compensation, MeanVFE, 20 epochs, 2 GPUs x 3) thinned per 1.5-m bin to each platform's single-sweep in-grid count, then the label recount; in-run eval on single-sweep nuScenes val. Read: O_N (25743 / 31818) - L'_K = structure at equal count; L'_K - R_acc (27468 / 27804 on nuScenes val) = count part of the density term." \
  scripts/submit.sh --partition=a100,a6000_ada,a6000,rtx8000 --gres=gpu:2 --cpus-per-task=20 --mem=150G --time=24:00:00 \
  --exclude=node03 --job-name=i43bL${SEED: -1} scripts/run_sourceonly_2gpu.sh "$CFG" 20261109_i43b_lprime_seed$SEED \
  i43b-lprime-k-seed$SEED ${FLAGS[@]+"${FLAGS[@]}"} < /dev/null | jid)
[ -n "$T" ] || { echo "submission of seed $SEED failed" >&2; exit 3; }
echo "item43b seed $SEED: $T"
